// Keeps the phone's screen on while the page is open. Uses the Screen Wake Lock
// API where browsers allow it (HTTPS or localhost); over plain http on the LAN
// it doesn't exist, so it loops a tiny silent video instead, which phones also
// treat as "keep awake". Both stop when the page is hidden and resume on return.

// 2 s of a 16×16 black H.264 frame, no audio.
const SILENT_VIDEO = "data:video/mp4;base64,";

export function createKeepAwake() {
  let enabled = false;
  let lock = null;
  let video = null;

  async function acquire() {
    if (!enabled || document.visibilityState !== "visible") return;
    if ("wakeLock" in navigator) {
      try {
        lock = await navigator.wakeLock.request("screen");
        return;
      } catch {
        // Not allowed right now (e.g. battery saver); try the video.
      }
    }
    video ??= silentVideo();
    video.play().catch(() => {}); // needs a tap first on some phones; set() is called from one
  }

  document.addEventListener("visibilitychange", acquire);

  return {
    /** Call from a tap the first time, so the video fallback may start. */
    set(on) {
      enabled = on;
      if (on) return acquire();
      lock?.release();
      lock = null;
      video?.pause();
    },
  };
}

function silentVideo() {
  const video = Object.assign(document.createElement("video"), {
    src: SILENT_VIDEO,
    muted: true,
    loop: true,
    playsInline: true,
  });
  video.setAttribute("aria-hidden", "true");
  video.style.cssText = "position: fixed; width: 1px; height: 1px; opacity: 0; pointer-events: none;";
  document.body.append(video);
  return video;
}
